package cn.bidcheck.service;

import cn.bidcheck.domain.Domain.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import static cn.bidcheck.service.BidService.*;
import static org.junit.jupiter.api.Assertions.*;

class SupplementAttachmentSnapshotTest {
    Map<String,Object> row(String id,String cp){return fields("attachmentId",id,"documentId","doc-"+id,"sha256","hash-"+id,"version",1,"checkpointId",cp,"claimId","claim","originRunId","run","status","READY","name","proof.pdf");}
    Finding finding(String id,List<String> dependencies){return new Finding("f-"+id,"run",new Checkpoint(id,id,"人员","HIGH","SEMANTIC_RESPONSE","role","EXISTS","人员","",true,true,true,null),new Evaluation("PASS","符合","",cn.bidcheck.compat.Java8Api.listOf(),1,"RULE"),cn.bidcheck.compat.Java8Api.mapOf("atomicCheck", cn.bidcheck.compat.Java8Api.mapOf("proof", cn.bidcheck.compat.Java8Api.mapOf("dependencyCheckpointIds", dependencies))));}
    @Test void onlyBoundItemAndExplicitTransitiveDependenciesReceiveSupplement(){cn.bidcheck.service.SupplementAttachmentSnapshot.Snapshot snapshot=SupplementAttachmentSnapshot.from(cn.bidcheck.compat.Java8Api.listOf(),cn.bidcheck.compat.Java8Api.listOf(row("a","person")),cn.bidcheck.compat.Java8Api.listOf(finding("person",cn.bidcheck.compat.Java8Api.listOf()), finding("performance",cn.bidcheck.compat.Java8Api.listOf("person")), finding("summary",cn.bidcheck.compat.Java8Api.listOf("performance")), finding("unrelated",cn.bidcheck.compat.Java8Api.listOf())));
        assertEquals(cn.bidcheck.compat.Java8Api.setOf("person", "performance", "summary"),snapshot.affectedCheckpointIds());assertEquals(1,snapshot.manifest().size());assertEquals(snapshot.affectedCheckpointIds(),new HashSet<>((List<String>)snapshot.manifest().get(0).get("affectedCheckpointIds")));}
    @Test void parseFailuresAndUnboundSourcesDoNotEnterFrozenEvidence(){java.util.Map<java.lang.String, java.lang.Object> failed=row("a","cp");failed.put("status","FAILED");java.util.Map<java.lang.String, java.lang.Object> unbound=row("b","");cn.bidcheck.service.SupplementAttachmentSnapshot.Snapshot snapshot=SupplementAttachmentSnapshot.from(cn.bidcheck.compat.Java8Api.listOf(),cn.bidcheck.compat.Java8Api.listOf(failed, unbound),cn.bidcheck.compat.Java8Api.listOf());assertTrue(snapshot.manifest().isEmpty());assertEquals("",snapshot.digest());assertTrue(snapshot.affectedCheckpointIds().isEmpty());}
    @Test void retryWithSameManifestDoesNotInvalidateAgainAndDigestTracksBytesAndBinding(){cn.bidcheck.service.SupplementAttachmentSnapshot.Snapshot first=SupplementAttachmentSnapshot.from(cn.bidcheck.compat.Java8Api.listOf(),cn.bidcheck.compat.Java8Api.listOf(row("a","cp")),cn.bidcheck.compat.Java8Api.listOf());cn.bidcheck.service.SupplementAttachmentSnapshot.Snapshot retry=SupplementAttachmentSnapshot.from(first.manifest(),cn.bidcheck.compat.Java8Api.listOf(row("a","cp")),cn.bidcheck.compat.Java8Api.listOf());assertEquals(first.digest(),retry.digest());assertTrue(retry.affectedCheckpointIds().isEmpty());
        java.util.Map<java.lang.String, java.lang.Object> changed=row("a","cp2");assertNotEquals(first.digest(),SupplementAttachmentSnapshot.from(cn.bidcheck.compat.Java8Api.listOf(),cn.bidcheck.compat.Java8Api.listOf(changed),cn.bidcheck.compat.Java8Api.listOf()).digest());changed=row("a","cp");changed.put("sha256","different");assertNotEquals(first.digest(),SupplementAttachmentSnapshot.from(cn.bidcheck.compat.Java8Api.listOf(),cn.bidcheck.compat.Java8Api.listOf(changed),cn.bidcheck.compat.Java8Api.listOf()).digest());}
}
